from dataclasses import dataclass
from itertools import product

@dataclass(frozen=True)
class Effect:
    participants: frozenset
    before: tuple
    after: tuple

    def closure(self, machine_states):
        for state in machine_states:
            if all(state[i] == value for i, value in self.before):
                update = dict(self.after)
                yield state, tuple(update.get(i, value) for i, value in enumerate(state))

A = Effect(frozenset({0}), ((0, 0),), ((0, 1),))
else_A = Effect(frozenset({0}), ((0, 0),), ((0, 2),))
B = Effect(frozenset({0, 1}), ((0, 0), (1, 0)), ((0, 2), (1, 0)))
states = list(product(range(3), repeat=2))
closed = {effect: set(effect.closure(states)) for effect in (A, else_A, B)}
assert else_A not in {A, B}
assert closed[else_A] & closed[B] == {((0, 0), (2, 0))}

def classes(machine_step, p_wills_A, post_wills_A):
    found = set()
    if p_wills_A and not post_wills_A and machine_step in closed[A]:
        found.add("A")
    if not p_wills_A and not post_wills_A and machine_step in closed[else_A]:
        found.add("A")
    if p_wills_A == post_wills_A and machine_step in closed[B]:
        found.add("B")
    return found

first = classes(((0, 0), (1, 0)), True, False)
middle = classes(((0, 0), (2, 0)), False, False)
last = classes(((0, 0), (2, 0)), True, True)
assert (first, middle, last) == ({"A"}, {"A", "B"}, {"B"})
assert first & middle and middle & last and not first & last
keys = {A: "A", else_A: "A", B: "B"}
assert keys[else_A] != keys[B] and closed[else_A] & closed[B]
print("The branch model gives {A}, {A,B}, {B}; class-keyed closure rejects the overlap.")

P, singleton = frozenset({0, 1}), frozenset({0})
ambient_classes = {"Befriend": P}
assert all(q <= P for q in ambient_classes.values())
assert not all(q <= singleton for q in ambient_classes.values())
assert not {k for k,q in ambient_classes.items() if q <= singleton}
eligible = {k for k,q in ambient_classes.items() if 0 in q}
before, after = set(), {"Befriend"}
assert before != after and before <= eligible and after <= eligible
assert not {k for k,q in ambient_classes.items() if 2 in q}
print("The singleton typing fails for binary Befriend; ambient classes admit the local change only for participants.")
